{"command": "python3 - <<'EOF'
import socket, struct
def raw_dns(name, qtype):
    tid=0x4321; flags=0x0100
    header=struct.pack(">HHHHHH", tid, flags, 1,0,0,0)
    qname=b"".join(bytes([len(p)])+p.encode(errors="ignore") for p in name.split("."))+b"\x00"
    pkt=header+qname+struct.pack(">HH", qtype, 1)
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(3)
    try:
        s.sendto(pkt,("127.0.0.11",53)); data,_=s.recvfrom(4096)
        return struct.unpack(">H",data[6:8])[0], (struct.unpack(">H",data[2:4])[0]&0xF)
    finally: s.close()

# AAAA (28) and PTR for the subnet hosts
for name,qt in [("prices.internal",28),("3.0.27.172.in-addr.arpa",12),("2.0.27.172.in-addr.arpa",12),("4.0.27.172.in-addr.arpa",12)]:
    print(name, "qtype",qt, "-> answers/rcode:", raw_dns(name,qt))
EOF"}

